mapper.select:
SELECT SUM(IFNULL(group_totals.total_qty,0)) AS qty, group_totals.location_id AS locationId, group_totals.lots_number AS lotsNumber, group_totals.expired_date AS expiredDate FROM ${warehouseId}_group_totals AS group_totals WHERE product_id = #{productId} AND location_group_id = #{warehouseId} AND location_id IN ( SELECT id FROM locations WHERE location_group_id = #{warehouseId}
AND is_for_sale = 1
) GROUP BY location_id, product_id, lots_number, expired_date HAVING SUM(group_totals.total_qty) > 0 ORDER BY group_totals.expired_date, group_totals.lots_number, group_totals.total_qty ASC LIMIT 1

SELECT SUM(IFNULL(group_totals.qty,0)) AS qty, group_totals.sales_order_id AS salesInvoiceId, group_totals.product_id AS productId, group_totals.location_group_id AS locationGroupId, group_totals.location_id AS locationId, group_totals.lots_number AS lotsNumber, group_totals.expired_date AS expiredDate FROM stock_orders AS group_totals WHERE product_id = #{productId} AND sales_order_id = #{salesInvoiceId} AND location_group_id = #{warehouseId} AND location_id IN ( SELECT id FROM locations WHERE location_group_id = #{warehouseId}
AND is_for_sale = 1
) GROUP BY location_id, product_id, lots_number, expired_date HAVING SUM(group_totals.qty) > 0 ORDER BY group_totals.expired_date, group_totals.lots_number, group_totals.qty ASC

